using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using VietCommerce.Core.Common;
using VietCommerce.Core.Entities.Users;

namespace VietCommerce.Core.Entities.Rituals;

/// <summary>
/// Logs all recommendations generated by the system for auditing and analysis.
/// Tracks which rituals were recommended, confidence scores, and user interactions.
/// </summary>
public class RecommendationLogEntity : AuditableEntity
{
    /// <summary>
    /// User ID who received the recommendation
    /// </summary>
    public Guid UserId { get; set; }

    /// <summary>
    /// Session ID during which the recommendation was generated
    /// </summary>
    [MaxLength(450)]
    public string SessionId { get; set; } = string.Empty;

    /// <summary>
    /// Ritual ID that was recommended
    /// </summary>
    public Guid RitualId { get; set; }

    /// <summary>
    /// Confidence score (0-1) of the pattern match
    /// </summary>
    [Column(TypeName = "decimal(3,2)")]
    public decimal ConfidenceScore { get; set; }

    /// <summary>
    /// JSON array of product IDs that were identified as missing
    /// </summary>
    public string MissingItemsJson { get; set; } = string.Empty;

    /// <summary>
    /// JSON object containing matching metadata
    /// Example: {"matchedSequenceLength": 5, "totalSequenceLength": 8, "matchedActionIndices": [0, 2, 4, 6, 7]}
    /// </summary>
    public string MatchingMetadataJson { get; set; } = string.Empty;

    /// <summary>
    /// Timestamp when the recommendation was displayed to the user
    /// </summary>
    public DateTime DisplayedAt { get; set; } = DateTime.UtcNow;

    /// <summary>
    /// User interaction with the recommendation
    /// Values: "viewed", "dismissed", "clicked", null (not interacted)
    /// </summary>
    [MaxLength(50)]
    public string? UserInteraction { get; set; }

    /// <summary>
    /// Timestamp of user interaction (if any)
    /// </summary>
    public DateTime? InteractionAt { get; set; }

    /// <summary>
    /// JSON object containing the system report with matching logic
    /// Example: {"matchedPattern": [...], "matchingSteps": [...], "reasonsForMissingItems": {...}}
    /// </summary>
    public string SystemReportJson { get; set; } = string.Empty;

    /// <summary>
    /// Navigation property to User
    /// </summary>
    [ForeignKey(nameof(UserId))]
    public virtual User? User { get; set; }

    /// <summary>
    /// Navigation property to Ritual
    /// </summary>
    [ForeignKey(nameof(RitualId))]
    public virtual RitualEntity? Ritual { get; set; }
}
